// Command vipps-webhook-register manages the Vipps ePayment webhook
// registration for this merchant. Vipps webhooks are not configured in the
// portal — they are registered via the Webhooks API, and the signing secret is
// generated by Vipps and returned only in the registration response.
//
// Usage:
//
//	vipps-webhook-register register [callback-url]   # register + print id/secret
//	vipps-webhook-register list                       # list registered webhooks
//	vipps-webhook-register delete <id>                # remove a webhook
//
// With no callback-url, register derives it from DOMAIN as
// https://<DOMAIN>/api/v1/vipps/webhooks. After registering, copy the printed
// secret into VIPPS_WEBHOOK_SECRET in /etc/brygge/env — it is never shown
// again. This is the operator step for BRY-200; run it once per environment
// after vipps-verify confirms the credentials.
//
// Exit status is 0 on success and 1 on any failure.
package main

import (
	"context"
	"fmt"
	"os"
	"time"

	"github.com/rs/zerolog"

	"github.com/brygge-klubb/brygge/internal/config"
	"github.com/brygge-klubb/brygge/internal/vipps"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(1)
	}

	cfg := config.Load()
	log := zerolog.New(zerolog.ConsoleWriter{Out: os.Stderr, TimeFormat: time.RFC3339}).
		With().Timestamp().Str("service", "vipps-webhook-register").Logger()

	if missing := missingCreds(cfg); len(missing) > 0 {
		fmt.Fprintf(os.Stderr, "vipps-webhook-register: missing required credentials: %v\n", missing)
		fmt.Fprintf(os.Stderr, "set them in /etc/brygge/env (see deploy/.env.example) and retry\n")
		os.Exit(1)
	}

	client := vipps.New(cfg.VippsBaseURL(), cfg.VippsClientID, cfg.VippsClientSecret,
		cfg.VippsSubscriptionKey, cfg.VippsMSN, log)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	switch os.Args[1] {
	case "register":
		callbackURL := defaultCallbackURL(cfg.Domain)
		if len(os.Args) >= 3 && os.Args[2] != "" {
			callbackURL = os.Args[2]
		}
		if callbackURL == "" {
			fmt.Fprintln(os.Stderr, "register: no callback URL and DOMAIN is unset")
			os.Exit(1)
		}
		res, err := client.RegisterWebhook(ctx, callbackURL)
		if err != nil {
			fmt.Fprintf(os.Stderr, "FAIL — registration rejected (%s, MSN %s, test_mode=%t)\n  %v\n",
				cfg.VippsBaseURL(), cfg.VippsMSN, cfg.VippsTestMode, err)
			os.Exit(1)
		}
		fmt.Printf("OK — webhook registered\n")
		fmt.Printf("  url:    %s\n", callbackURL)
		fmt.Printf("  id:     %s\n", res.ID)
		fmt.Printf("  secret: %s\n", res.Secret)
		fmt.Printf("\nCopy the secret into VIPPS_WEBHOOK_SECRET in /etc/brygge/env — it is not shown again.\n")

	case "list":
		hooks, err := client.ListWebhooks(ctx)
		if err != nil {
			fmt.Fprintf(os.Stderr, "FAIL — list failed: %v\n", err)
			os.Exit(1)
		}
		if len(hooks) == 0 {
			fmt.Println("no webhooks registered")
			return
		}
		for _, h := range hooks {
			fmt.Printf("  %s  %s  %v\n", h.ID, h.URL, h.Events)
		}

	case "delete":
		if len(os.Args) < 3 || os.Args[2] == "" {
			fmt.Fprintln(os.Stderr, "delete: missing webhook id")
			os.Exit(1)
		}
		if err := client.DeleteWebhook(ctx, os.Args[2]); err != nil {
			fmt.Fprintf(os.Stderr, "FAIL — delete failed: %v\n", err)
			os.Exit(1)
		}
		fmt.Printf("OK — webhook %s deleted\n", os.Args[2])

	default:
		usage()
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: vipps-webhook-register register [callback-url] | list | delete <id>")
}

func defaultCallbackURL(domain string) string {
	if domain == "" || domain == "localhost" {
		return ""
	}
	return "https://" + domain + "/api/v1/vipps/webhooks"
}

func missingCreds(cfg config.Config) []string {
	missing := make([]string, 0, 4)
	if cfg.VippsClientID == "" {
		missing = append(missing, "VIPPS_CLIENT_ID")
	}
	if cfg.VippsClientSecret == "" {
		missing = append(missing, "VIPPS_CLIENT_SECRET")
	}
	if cfg.VippsSubscriptionKey == "" {
		missing = append(missing, "VIPPS_SUBSCRIPTION_KEY")
	}
	if cfg.VippsMSN == "" {
		missing = append(missing, "VIPPS_MSN")
	}
	return missing
}
